_ITEM_TYPE_FALLBACK = {
    "POTION": "potion",
    "WEAPON": "sword",
    "ARMOR": "armor",
    "SCROLL": "book",
    "ARTIFACT": "ring",
}

DEFAULT_BG_KEY = "arctic_icebergs"
FALLBACK_ITEM_KEY = "gem"


def get_bg_art(key=None):
    """Return a background landscape by key (default: arctic icebergs)."""
    if not key:
        return BG_ART[DEFAULT_BG_KEY]
    return BG_ART.get(key, BG_ART[DEFAULT_BG_KEY])


def get_ui_art(key, default=None):
    """Return a UI panel art by key, or ``default`` when missing."""
    return UI_ART.get(key, default)


def get_menu_art(key, default=None):
    """Return a menu frame/rule art by key, or ``default`` when missing."""
    return MENU_ART.get(key, default)


def get_item_art_key(name="", item_type=None):
    """Resolve an item to an ITEM_ART key using keywords, then item type."""
    text = (name or "").lower()
    for keyword, art_key in _ITEM_KEYWORDS:
        if keyword in text:
            return art_key
    if item_type:
        return _ITEM_TYPE_FALLBACK.get(str(item_type).upper(), FALLBACK_ITEM_KEY)
    return FALLBACK_ITEM_KEY


def get_item_art(name="", item_type=None):
    """Return ASCII art text for an item name/type (never empty)."""
    return ITEM_ART.get(get_item_art_key(name, item_type), ITEM_ART[FALLBACK_ITEM_KEY])


def item_art_dimensions(art):
    """Return (rows, cols) for a stored art block."""
    lines = art.split("\n") if art else []
    return len(lines), max((len(line) for line in lines), default=0)
